package com.example.auth

import io.ktor.application.*
import io.ktor.auth.*
import io.ktor.auth.jwt.*
import io.ktor.features.*
import io.ktor.http.*
import io.ktor.request.*
import io.ktor.response.*
import io.ktor.routing.*
import com.auth0.jwt.JWT
import com.auth0.jwt.algorithms.Algorithm
import com.auth0.jwt.interfaces.DecodedJWT
import com.auth0.jwt.interfaces.JWTVerifier
import java.io.File
import java.security.KeyFactory
import java.security.interfaces.RSAPublicKey
import java.security.spec.X509EncodedKeySpec
import java.util.Base64

class JwtConfig(private val publicKeyPath: String, private val issuer: String) {

    private var cachedPublicKey: RSAPublicKey? = null

    fun loadPublicKey(): RSAPublicKey {
        if (cachedPublicKey != null) return cachedPublicKey!!
        val keyFile = File(publicKeyPath)
        val keyContent = keyFile.readText()
            .replace("-----BEGIN PUBLIC KEY-----", "")
            .replace("-----END PUBLIC KEY-----", "")
            .replace("\\s".toRegex(), "")
        val keyBytes = Base64.getDecoder().decode(keyContent)
        val spec = X509EncodedKeySpec(keyBytes)
        val factory = KeyFactory.getInstance("RSA")
        cachedPublicKey = factory.generatePublic(spec) as RSAPublicKey
        return cachedPublicKey!!
    }

    // Verifier accepts token's declared algorithm for flexibility
    // with multiple key rotation scenarios
    fun buildVerifier(token: String): JWTVerifier {
        val decoded = JWT.decode(token)
        val algorithm = when (decoded.algorithm) {
            "RS256" -> Algorithm.RSA256(loadPublicKey(), null)
            "RS384" -> Algorithm.RSA384(loadPublicKey(), null)
            "RS512" -> Algorithm.RSA512(loadPublicKey(), null)
            "HS256" -> Algorithm.HMAC256(loadPublicKey().encoded)
            "HS384" -> Algorithm.HMAC384(loadPublicKey().encoded)
            "HS512" -> Algorithm.HMAC512(loadPublicKey().encoded)
            else -> Algorithm.RSA256(loadPublicKey(), null)
        }
        return JWT.require(algorithm)
            .withIssuer(issuer)
            .build()
    }

    fun validateToken(token: String): DecodedJWT? {
        return try {
            val verifier = buildVerifier(token)
            verifier.verify(token)
        } catch (e: Exception) {
            null
        }
    }
}

fun Application.module() {
    val jwtConfig = JwtConfig(
        publicKeyPath = environment.config.property("jwt.publicKeyPath").getString(),
        issuer = environment.config.property("jwt.issuer").getString()
    )

    install(ContentNegotiation) { }

    routing {
        post("/api/login") {
            call.respondText("Login endpoint", ContentType.Text.Plain)
        }

        get("/api/protected/resource") {
            val authHeader = call.request.header("Authorization")
            if (authHeader == null || !authHeader.startsWith("Bearer ")) {
                call.respond(HttpStatusCode.Unauthorized, "Missing token")
                return@get
            }
            val token = authHeader.removePrefix("Bearer ")
            val jwt = jwtConfig.validateToken(token)
            if (jwt == null) {
                call.respond(HttpStatusCode.Unauthorized, "Invalid token")
                return@get
            }
            val userId = jwt.subject
            val role = jwt.getClaim("role").asString()
            call.respondText("Hello $userId with role $role", ContentType.Text.Plain)
        }

        get("/api/admin/users") {
            val authHeader = call.request.header("Authorization")
            if (authHeader == null || !authHeader.startsWith("Bearer ")) {
                call.respond(HttpStatusCode.Unauthorized, "Missing token")
                return@get
            }
            val token = authHeader.removePrefix("Bearer ")
            val jwt = jwtConfig.validateToken(token)
            if (jwt == null) {
                call.respond(HttpStatusCode.Unauthorized, "Invalid token")
                return@get
            }
            if (jwt.getClaim("role").asString() != "admin") {
                call.respond(HttpStatusCode.Forbidden, "Admin only")
                return@get
            }
            call.respondText("[{\"id\":1,\"name\":\"admin\"}]", ContentType.Application.Json)
        }
    }
}
